var embeddings_default = "---\nlayout: article\ntitle: Embeddings\ndescription: Generate text embeddings with Appwrite VectorsDB. Turn text into vector embeddings with built-in models and store them in your documents for vector search.\n---\nAn embedding is a list of numbers that represents the meaning of a piece of text.\nVectorsDB can generate embeddings for you with built-in models, so you can turn text into vectors and store them in a collection without running a separate embedding service.\n\nThe typical flow is two steps: generate an embedding from your text, then store that embedding in a document's `embeddings` field. Once stored, you can run [vector search](/docs/products/databases/vectorsdb/vector-search) over your documents.\n\n# Generate embeddings {% #generate-embeddings %}\nUse the `createTextEmbeddings` method to turn one or more strings into vector embeddings. Pass an array of `texts` and, optionally, a `model`. When you omit `model`, VectorsDB uses the default `nomic-embed-text` model. Appwrite [Server SDKs](/docs/sdks#server) require an [API key](/docs/advanced/platform/api-keys).\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createTextEmbeddings({\n    texts: ['The quick brown fox jumps over the lazy dog'],\n    model: sdk.EmbeddingModel.Nomicembedtext // optional, defaults to nomic-embed-text\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createTextEmbeddings({\n    texts: ['The quick brown fox jumps over the lazy dog'],\n    model: sdk.EmbeddingModel.Nomicembedtext // optional, defaults to nomic-embed-text\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\Enums\\EmbeddingModel;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$result = $vectorsDB->createTextEmbeddings(\n    texts: ['The quick brown fox jumps over the lazy dog'],\n    model: EmbeddingModel::NOMICEMBEDTEXT() // optional, defaults to nomic-embed-text\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.enums import EmbeddingModel\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\nresult = vectors_db.create_text_embeddings(\n    texts = ['The quick brown fox jumps over the lazy dog'],\n    model = EmbeddingModel.NOMIC_EMBED_TEXT # optional, defaults to nomic-embed-text\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\ninclude Appwrite::Enums\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\nresult = vectors_db.create_text_embeddings(\n    texts: ['The quick brown fox jumps over the lazy dog'],\n    model: EmbeddingModel::NOMIC_EMBED_TEXT # optional, defaults to nomic-embed-text\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Enums;\nusing Appwrite.Models;\nusing Appwrite.Services;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nEmbeddingList result = await vectorsDB.CreateTextEmbeddings(\n    texts: new List<string> { \"The quick brown fox jumps over the lazy dog\" },\n    model: EmbeddingModel.NomicEmbedText // optional, defaults to nomic-embed-text\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\nimport 'package:dart_appwrite/enums.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nEmbeddingList result = await vectorsDB.createTextEmbeddings(\n    texts: ['The quick brown fox jumps over the lazy dog'],\n    model: EmbeddingModel.nomicEmbedText, // optional, defaults to nomic-embed-text\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.enums.EmbeddingModel\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval response = vectorsDB.createTextEmbeddings(\n    texts = listOf(\"The quick brown fox jumps over the lazy dog\"),\n    model = EmbeddingModel.NOMIC_EMBED_TEXT, // optional, defaults to nomic-embed-text\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.enums.EmbeddingModel;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\nimport java.util.List;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvectorsDB.createTextEmbeddings(\n    List.of(\"The quick brown fox jumps over the lazy dog\"),\n    EmbeddingModel.NOMIC_EMBED_TEXT, // optional, defaults to nomic-embed-text\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\nimport AppwriteEnums\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet embeddingList = try await vectorsDB.createTextEmbeddings(\n    texts: [\"The quick brown fox jumps over the lazy dog\"],\n    model: .nomicEmbedText // optional, defaults to nomic-embed-text\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::enums::EmbeddingModel;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let result = vectors_db.create_text_embeddings(\n        vec![\"The quick brown fox jumps over the lazy dog\"],\n        Some(EmbeddingModel::NomicEmbedText), // optional, defaults to nomic-embed-text\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db create-text-embeddings \\\n    --texts 'The quick brown fox jumps over the lazy dog' \\\n    --model 'nomic-embed-text'\n```\n{% /multicode %}\n\nThe response is an embedding list. The `embeddings` array holds one entry per input text, in the same order you passed them.\n\n```json\n{\n    \"total\": 1,\n    \"embeddings\": [\n        {\n            \"model\": \"nomic-embed-text\",\n            \"dimension\": 768,\n            \"embedding\": [-0.012246467, 0.02621112, -0.15247375, ...],\n            \"error\": \"\"\n        }\n    ]\n}\n```\n\nEach entry contains:\n\n| Field | Description |\n| --- | --- |\n| `model` | The model that generated this embedding. |\n| `dimension` | The number of values in the embedding vector. |\n| `embedding` | The embedding vector as an array of floats. If generation fails, this is an empty array. |\n| `error` | An error message if this text could not be embedded. An empty string means there was no error. |\n\n# Available models {% #available-models %}\nVectorsDB ships with the following text embedding models. The `dimension` of a model is the length of the vector it produces, and it must match the `dimension` you set on the [collection](/docs/products/databases/vectorsdb/collections) where you store the embeddings.\n\n| Model | Dimension | Notes |\n| --- | --- | --- |\n| `nomic-embed-text` | 768 | Default model, used when you omit `model`. |\n| `embedding-gemma` | 768 | |\n| `all-minilm` | 384 | |\n| `bge-small` | 384 | |\n\n{% info title=\"Match the model to your collection dimension\" %}\nPick a model before you create your collection, then set the collection's `dimension` to that model's dimension. All documents in a collection must use vectors of the same dimension, so a single collection works with models of one dimension only.\n{% /info %}\n\n# Store embeddings {% #store-embeddings %}\nOnce you have an embedding, store it in a document's `embeddings` field. The collection's `dimension` must match the embedding's `dimension`. You can store any related data alongside the vector in the document's `metadata` field.\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst text = 'The quick brown fox jumps over the lazy dog';\n\nconst embeddings = await vectorsDB.createTextEmbeddings({\n    texts: [text]\n});\n\nconst result = await vectorsDB.createDocument({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: sdk.ID.unique(),\n    data: {\n        embeddings: embeddings.embeddings[0].embedding,\n        metadata: { text }\n    }\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst text = 'The quick brown fox jumps over the lazy dog';\n\nconst embeddings = await vectorsDB.createTextEmbeddings({\n    texts: [text]\n});\n\nconst result = await vectorsDB.createDocument({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: sdk.ID.unique(),\n    data: {\n        embeddings: embeddings.embeddings[0].embedding,\n        metadata: { text }\n    }\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\ID;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$text = 'The quick brown fox jumps over the lazy dog';\n\n$embeddings = $vectorsDB->createTextEmbeddings(\n    texts: [$text]\n);\n\n$result = $vectorsDB->createDocument(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: ID::unique(),\n    data: [\n        'embeddings' => $embeddings['embeddings'][0]['embedding'],\n        'metadata' => ['text' => $text]\n    ]\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.id import ID\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\ntext = 'The quick brown fox jumps over the lazy dog'\n\nembeddings = vectors_db.create_text_embeddings(\n    texts = [text]\n)\n\nresult = vectors_db.create_document(\n    database_id = '<DATABASE_ID>',\n    collection_id = '<COLLECTION_ID>',\n    document_id = ID.unique(),\n    data = {\n        \"embeddings\": embeddings[\"embeddings\"][0][\"embedding\"],\n        \"metadata\": { \"text\": text }\n    }\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\ntext = 'The quick brown fox jumps over the lazy dog'\n\nembeddings = vectors_db.create_text_embeddings(\n    texts: [text]\n)\n\nresult = vectors_db.create_document(\n    database_id: '<DATABASE_ID>',\n    collection_id: '<COLLECTION_ID>',\n    document_id: ID.unique(),\n    data: {\n        \"embeddings\" => embeddings.embeddings[0].embedding,\n        \"metadata\" => { \"text\" => text }\n    }\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Models;\nusing Appwrite.Services;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvar text = \"The quick brown fox jumps over the lazy dog\";\n\nEmbeddingList embeddings = await vectorsDB.CreateTextEmbeddings(\n    texts: new List<string> { text }\n);\n\nDocument result = await vectorsDB.CreateDocument(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    documentId: ID.Unique(),\n    data: new {\n        embeddings = embeddings.Embeddings[0].Embedding,\n        metadata = new { text }\n    }\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nfinal text = 'The quick brown fox jumps over the lazy dog';\n\nEmbeddingList embeddings = await vectorsDB.createTextEmbeddings(\n    texts: [text],\n);\n\nDocument result = await vectorsDB.createDocument(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: ID.unique(),\n    data: {\n        \"embeddings\": embeddings.embeddings[0].embedding,\n        \"metadata\": { \"text\": text }\n    },\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.ID\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval text = \"The quick brown fox jumps over the lazy dog\"\n\nval embeddings = vectorsDB.createTextEmbeddings(\n    texts = listOf(text),\n)\n\nval response = vectorsDB.createDocument(\n    databaseId = \"<DATABASE_ID>\",\n    collectionId = \"<COLLECTION_ID>\",\n    documentId = ID.unique(),\n    data = mapOf(\n        \"embeddings\" to embeddings.embeddings[0].embedding,\n        \"metadata\" to mapOf(\"text\" to text)\n    ),\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.ID;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\nimport java.util.List;\nimport java.util.Map;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nString text = \"The quick brown fox jumps over the lazy dog\";\n\nvectorsDB.createTextEmbeddings(\n    List.of(text),\n    new CoroutineCallback<>((embeddings, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        vectorsDB.createDocument(\n            \"<DATABASE_ID>\",\n            \"<COLLECTION_ID>\",\n            ID.unique(),\n            Map.of(\n                \"embeddings\", embeddings.getEmbeddings().get(0).getEmbedding(),\n                \"metadata\", Map.of(\"text\", text)\n            ),\n            new CoroutineCallback<>((result, err) -> {\n                if (err != null) {\n                    err.printStackTrace();\n                    return;\n                }\n\n                System.out.println(result);\n            })\n        );\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet text = \"The quick brown fox jumps over the lazy dog\"\n\nlet embeddings = try await vectorsDB.createTextEmbeddings(\n    texts: [text]\n)\n\nlet document = try await vectorsDB.createDocument(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    documentId: ID.unique(),\n    data: [\n        \"embeddings\": embeddings.embeddings[0].embedding,\n        \"metadata\": [\"text\": text]\n    ]\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::id::ID;\nuse serde_json::json;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let text = \"The quick brown fox jumps over the lazy dog\";\n\n    let embeddings = vectors_db.create_text_embeddings(\n        vec![text],\n        None, // model (optional)\n    ).await?;\n\n    let result = vectors_db.create_document(\n        \"<DATABASE_ID>\",\n        \"<COLLECTION_ID>\",\n        ID::unique(),\n        json!({\n            \"embeddings\": embeddings.embeddings[0].embedding,\n            \"metadata\": { \"text\": text }\n        }),\n        None, // permissions (optional)\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db create-document \\\n    --database-id <DATABASE_ID> \\\n    --collection-id <COLLECTION_ID> \\\n    --document-id 'unique()' \\\n    --data '{ \"embeddings\": [-0.012246467, 0.02621112, -0.15247375], \"metadata\": { \"text\": \"The quick brown fox jumps over the lazy dog\" } }'\n```\n{% /multicode %}\n\n{% info title=\"Embed in batches\" %}\nYou can pass several strings in one `createTextEmbeddings` call to embed them together. The response returns one entry per input text, in order, so you can map each embedding back to its source text before storing.\n{% /info %}\n\n# Next steps {% #next-steps %}\nWith embeddings stored in your documents, you can find the most similar documents to a query vector with vector search.\n\n{% arrow_link href=\"/docs/products/databases/vectorsdb/vector-search\" %}\nLearn about vector search\n{% /arrow_link %}\n";
export { embeddings_default as default };
